// Generated by Trae Work
// Chart initialization for the senera capability assessment report.
// All charts share the single active chart palette (Business Blue) read from :root.

(function () {
  'use strict';

  var root = document.documentElement;
  var css = getComputedStyle(root);
  function token(name, fallback) {
    var value = css.getPropertyValue(name);
    value = value ? value.trim() : '';
    return value || fallback;
  }

  // One palette read for every chart in this report.
  var chartSeries = [
    token('--chart-series-1', '#0969DA'),
    token('--chart-series-2', '#8250DF'),
    token('--chart-series-3', '#06B6D4'),
    token('--chart-series-4', '#BF3989')
  ];
  var chartOther = token('--chart-other', '#D0D7DE');
  var chartGrid = token('--chart-grid', 'rgba(27, 31, 36, 0.12)');
  var chartAxis = token('--chart-axis', '#636C76');
  var chartLabel = token('--chart-label', '#636C76');
  var tooltipBg = token('--chart-tooltip-bg', '#FFFFFF');
  var pageBorder = token('--page-border', '#D0D7DE');
  var pageSurface = token('--page-surface', '#F6F8FA');
  var ink = token('--ink', '#1B1F24');

  var fontFamily =
    "'InstrumentSans', 'PingFang SC', 'Microsoft YaHei', 'Noto Sans CJK SC', sans-serif";

  if (typeof echarts === 'undefined') {
    showEmpty('radar-chart', 'radar-empty');
    showEmpty('coverage-chart', 'coverage-empty');
    return;
  }

  function showEmpty(chartId, emptyId) {
    var chartEl = document.getElementById(chartId);
    var emptyEl = document.getElementById(emptyId);
    if (chartEl) {
      chartEl.style.display = 'none';
    }
    if (emptyEl) {
      emptyEl.style.display = 'block';
    }
  }

  function baseTooltip() {
    return {
      appendToBody: true,
      backgroundColor: tooltipBg,
      borderColor: pageBorder,
      borderWidth: 1,
      textStyle: { color: ink, fontSize: 12, fontFamily: fontFamily }
    };
  }

  var instances = [];

  function mount(id, option) {
    var el = document.getElementById(id);
    if (!el) {
      return null;
    }
    var instance = echarts.init(el, null, { renderer: 'svg' });
    instance.setOption(option);
    instances.push(instance);
    return instance;
  }

  // ---- Figure 1: eight-dimension capability profile -------------------------
  var dimensions = [
    { name: '架构与模块化', score: 88 },
    { name: '运行时内核能力', score: 86 },
    { name: '工具生态与扩展性', score: 84 },
    { name: '记忆与学习体系', score: 80 },
    { name: '安全与治理', score: 82 },
    { name: '工程质量与验证', score: 87 },
    { name: '可观测性与运维', score: 85 },
    { name: '前端与产品完成度', score: 78 }
  ];

  var radarOption = {
    animation: false,
    tooltip: Object.assign(baseTooltip(), { trigger: 'item' }),
    radar: {
      center: ['50%', '54%'],
      radius: '64%',
      indicator: dimensions.map(function (item) {
        return { name: item.name, max: 100 };
      }),
      axisName: {
        color: chartLabel,
        fontSize: 11,
        fontFamily: fontFamily,
        lineHeight: 15
      },
      splitNumber: 5,
      splitLine: { lineStyle: { color: chartGrid, width: 1 } },
      splitArea: {
        areaStyle: { color: [pageSurface, '#FFFFFF'] }
      },
      axisLine: { lineStyle: { color: chartGrid, width: 1 } }
    },
    series: [
      {
        type: 'radar',
        symbol: 'circle',
        symbolSize: 4,
        lineStyle: { color: chartSeries[0], width: 2 },
        itemStyle: { color: chartSeries[0] },
        areaStyle: { color: chartSeries[0], opacity: 0.14 },
        data: [
          {
            value: dimensions.map(function (item) {
              return item.score;
            }),
            name: '能力评分'
          }
        ],
        tooltip: {
          formatter: function (params) {
            var lines = params.value.map(function (value, index) {
              return dimensions[index].name + '：' + value;
            });
            return lines.join('<br/>');
          }
        }
      }
    ]
  };

  // ---- Figure 2: coverage actual vs ratchet baseline ------------------------
  var coverage = [
    { label: '前端 分支', actual: 59.73, threshold: 59 },
    { label: '前端 函数', actual: 66.66, threshold: 66 },
    { label: '前端 语句', actual: 66.91, threshold: 65 },
    { label: '前端 行', actual: 69.86, threshold: 68 },
    { label: '后端 分支', actual: 63.86, threshold: 60 },
    { label: '后端 语句', actual: 75.69, threshold: 73 },
    { label: '后端 函数', actual: 77.88, threshold: 73 },
    { label: '后端 行', actual: 78.52, threshold: 75 }
  ];

  var coverageOption = {
    animation: false,
    grid: { left: 4, right: 32, top: 44, bottom: 8, containLabel: true },
    tooltip: Object.assign(baseTooltip(), {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      valueFormatter: function (value) {
        return value + '%';
      }
    }),
    legend: {
      top: 0,
      left: 0,
      itemWidth: 10,
      itemHeight: 10,
      itemGap: 16,
      icon: 'circle',
      textStyle: { color: chartLabel, fontSize: 12, fontFamily: fontFamily }
    },
    xAxis: {
      type: 'value',
      min: 0,
      max: 100,
      axisLabel: {
        color: chartAxis,
        fontSize: 11,
        fontFamily: fontFamily,
        formatter: '{value}%'
      },
      axisLine: { lineStyle: { color: chartGrid } },
      splitLine: { lineStyle: { color: chartGrid, width: 1 } }
    },
    yAxis: {
      type: 'category',
      data: coverage.map(function (item) {
        return item.label;
      }),
      axisLabel: { color: chartLabel, fontSize: 11, fontFamily: fontFamily },
      axisLine: { lineStyle: { color: chartGrid } },
      axisTick: { show: false }
    },
    series: [
      {
        name: '实测覆盖率',
        type: 'bar',
        data: coverage.map(function (item) {
          return item.actual;
        }),
        itemStyle: { color: chartSeries[0], borderRadius: [0, 4, 4, 0] },
        barMaxWidth: 12,
        label: {
          show: true,
          position: 'right',
          color: chartLabel,
          fontSize: 11,
          fontFamily: fontFamily,
          formatter: '{c}%'
        }
      },
      {
        name: '棘轮基线',
        type: 'bar',
        data: coverage.map(function (item) {
          return item.threshold;
        }),
        itemStyle: { color: chartOther, borderRadius: [0, 4, 4, 0] },
        barMaxWidth: 12
      }
    ]
  };

  mount('radar-chart', radarOption);
  mount('coverage-chart', coverageOption);

  if (!instances.length) {
    showEmpty('radar-chart', 'radar-empty');
    showEmpty('coverage-chart', 'coverage-empty');
  }

  var resizeTimer = null;
  window.addEventListener('resize', function () {
    if (resizeTimer) {
      window.clearTimeout(resizeTimer);
    }
    resizeTimer = window.setTimeout(function () {
      instances.forEach(function (instance) {
        instance.resize();
      });
    }, 120);
  });
})();
